import React, { forwardRef, useImperativeHandle, useRef } from 'react';

import { TimeseriesChartLegend } from './components/legend/TimeseriesChartLegend.js';
import { TIMESERIES_CHART_DEFAULT_VARIANT } from './constants.js';
import { TimeseriesRawDataContext } from './context/TimeseriesRawData.context.js';
import { StoreProvider } from './providers/StoreProvider.js';
import { TimeseriesConfigProvider } from './providers/TimeseriesConfigProviders.js';
import { TimeseriesDataProvider } from './providers/TimeseriesDataProvider.js';
import { TimeseriesFilteredDataProvider } from './providers/TimeseriesFilteredDataProvider.js';
import { TimeseriesMinMaxXAxisProvider } from './providers/TimeseriesMinMaxXAxisProvider.js';
import { Annotations } from './slots/annotations/Annotations.js';
import { Marker } from './slots/annotations/Marker.js';
import { Track } from './slots/annotations/Track.js';
import { Legend } from './slots/Legend.js';
import { Area } from './slots/shapes/Area.js';
import { Band } from './slots/shapes/Band.js';
import { Bar } from './slots/shapes/Bar.js';
import { Line } from './slots/shapes/Line.js';
import { Threshold } from './slots/Threshold.js';
import { Tooltip } from './slots/Tooltip.js';
import { XAxis } from './slots/XAxis.js';
import { YAxis } from './slots/YAxis.js';
import { TimeseriesChart as _TimeseriesChart } from './TimeseriesChart.js';
import { TimeseriesChartProps } from './types/timeseries-props.js';
import { TimeseriesChartRef } from './types/timeseries-ref.js';
import { normalizeConfig } from './utils/chart-configuration.js';
import { buildAndDownloadCsv } from './utils/download/build-and-download-csv.js';
import {
  hasSeriesWithDatapoints,
  splitTimeseriesPerVariant,
} from './utils/timeseries.js';
import { useTimeseriesChartConfig } from './utils/useTimeseriesChartConfig.js';
import { useMergeRefs } from '../../core/hooks/useMergeRefs.js';
import { ChartLayout } from '../core/components/chart-layout/ChartLayout.js';
import { getChartStatesTemplates } from '../core/components/chart-states/functions/get-chart-states-template.js';
import { CATEGORICAL_LEGEND_SIZES } from '../core/components/legend/categorical/constants.js';
import { ChartSeriesActionContext } from '../core/components/series-action/ChartSeriesActionContext.js';
import { coerceSizeValue } from '../core/functions/coerceSizeValue.js';
import { EmptyStateSlot } from '../core/slots/chart-states/EmptyStateSlot.js';
import { ErrorStateSlot } from '../core/slots/chart-states/ErrorStateSlot.js';
import { ChartType } from '../core/types/chart-types.js';

/**
 * The default max height used for the timeserieschart when no explicit
 * height is given
 */
const TIMESERIES_CHART_DEFAULT_HEIGHT = 300;

/**
 * TimeseriesChart component
 */
export const TimeseriesChartRoot = forwardRef<
  TimeseriesChartRef,
  TimeseriesChartProps
>((props, forwardedRef) => {
  const {
    children,
    data,
    gapPolicy,
    pointsDisplay,
    colorPalette,
    truncationMode,
    variant = TIMESERIES_CHART_DEFAULT_VARIANT,
    valueRepresentation,
    height: heightProp,
    seriesActions,
    onMessage,
    loading = false,
    curve,
    className,
    style,
  } = props;

  const chartHeight =
    coerceSizeValue(heightProp) || TIMESERIES_CHART_DEFAULT_HEIGHT;
  const dataPerVariant = splitTimeseriesPerVariant(
    data ?? [],
    children,
    variant,
  );
  const config = useTimeseriesChartConfig(children, {
    gapPolicy,
    pointsDisplay,
    valueRepresentation,
    colorPalette,
    truncationMode,
    curve,
  });
  const { emptyState, errorState } = getChartStatesTemplates(children);

  const containerRef = useRef<HTMLDivElement>(null);
  const rootRef = useMergeRefs<TimeseriesChartRef | HTMLDivElement>([
    forwardedRef,
    containerRef,
  ]);

  const { shapePriority, ...rawDataPerVariant } = dataPerVariant;
  const hasSeries = hasSeriesWithDatapoints(dataPerVariant);
  const legendOrientation = config.legend.hidden
    ? undefined
    : config.legend.position;

  useImperativeHandle(forwardedRef, () => ({
    element: containerRef.current,
    getConfig: () =>
      JSON.stringify({
        type: ChartType.TimeSeries,
        ...normalizeConfig(config),
      }),
    downloadData: () => {
      buildAndDownloadCsv(rawDataPerVariant);
    },
  }));

  return (
    <TimeseriesConfigProvider config={config}>
      <TimeseriesRawDataContext.Provider value={rawDataPerVariant}>
        <TimeseriesDataProvider
          data={dataPerVariant}
          valueRepresentation={config.valueRepresentation}
          onMessage={onMessage}
        >
          <TimeseriesMinMaxXAxisProvider>
            <ChartSeriesActionContext.Provider
              value={{
                chartSeriesActions: seriesActions,
              }}
            >
              <StoreProvider>
                <TimeseriesFilteredDataProvider>
                  <ChartLayout
                    chartHeight={chartHeight}
                    resizable={config.legend.resizable}
                    isEmpty={!hasSeries}
                    emptyState={emptyState}
                    errorState={errorState}
                    showLoader={loading}
                    legendConfig={{
                      orientation: legendOrientation,
                      ratio: config.legend.ratio,
                      hidden: config.legend.hidden,
                      sizes: CATEGORICAL_LEGEND_SIZES,
                    }}
                    className={className}
                    style={style}
                  >
                    <ChartLayout.Graph>
                      <_TimeseriesChart {...props} ref={rootRef} />
                    </ChartLayout.Graph>
                    <ChartLayout.Legend>
                      {!config.legend.hidden && <TimeseriesChartLegend />}
                    </ChartLayout.Legend>
                  </ChartLayout>
                </TimeseriesFilteredDataProvider>
              </StoreProvider>
            </ChartSeriesActionContext.Provider>
          </TimeseriesMinMaxXAxisProvider>
        </TimeseriesDataProvider>
      </TimeseriesRawDataContext.Provider>
    </TimeseriesConfigProvider>
  );
});

TimeseriesChartRoot['displayName'] = 'TimeseriesChartRoot';

/**
 * The `TimeseriesChart` visually represents data in sequential order of time.
 * It's used to observe trends, patterns, and fluctuations in the data over a
 * specific time period.
 */
export const TimeseriesChart = Object.assign(TimeseriesChartRoot, {
  Band,
  Legend,
  YAxis,
  XAxis,
  Tooltip,
  Annotations,
  Line,
  Area,
  Bar,
  Threshold,
  EmptyState: EmptyStateSlot,
  ErrorState: ErrorStateSlot,
});

/** Annotations Slots */
export const TimeseriesAnnotations = Object.assign(
  {},
  {
    Marker,
    Track,
  },
);
